'use strict';
(()=>{
 const originals=new WeakMap(),attributes=new WeakMap();let scheduled=false;
 function translate(text){if(typeof frontendText==='undefined')return text;if(Object.hasOwn(frontendText,text))return frontendText[text];let result=text;const keys=Object.keys(frontendText).filter(k=>k&&frontendText[k]!==k).sort((a,b)=>b.length-a.length);if(!keys.length)return result;const escape=s=>s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');const expression=new RegExp(keys.map(k=>escape(k)).join('|'),'g');return result.replace(expression,key=>frontendText[key]);}
 function text(node){if(!node.nodeValue.trim()||node.parentElement?.closest('script,style,#brand-name,#instructions,#checkout-reference,#checkout-amount,#price-summary'))return;const old=originals.get(node);let source=!old||node.nodeValue!==old.output?node.nodeValue:old.source;const value=translate(source);originals.set(node,{source,output:value});if(value!==node.nodeValue)node.nodeValue=value;}
 function attrs(node){if(!node.hasAttribute)return;let saved=attributes.get(node)||{};for(const key of ['placeholder','aria-label','title','alt']){if(!node.hasAttribute(key))continue;const val=node.getAttribute(key),old=saved[key],source=!old||val!==old.output?val:old.source,output=translate(source);saved[key]={source,output};if(output!==val)node.setAttribute(key,output);}attributes.set(node,saved);if(node.matches('meta[name="description"]')){const val=node.content,old=saved.content,source=!old||val!==old.output?val:old.source,output=translate(source);saved.content={source,output};if(output!==val)node.content=output;}}
 function apply(){scheduled=false;const walker=document.createTreeWalker(document.documentElement,NodeFilter.SHOW_TEXT);let node;while((node=walker.nextNode()))text(node);document.querySelectorAll('[placeholder],[aria-label],[title],[alt],meta[name="description"]').forEach(attrs);}
 window.applyFrontendCopy=apply;
 const observer=new MutationObserver(()=>{if(!scheduled){scheduled=true;queueMicrotask(apply);}});observer.observe(document.documentElement,{childList:true,subtree:true,characterData:true});
})();
